import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// R2, we must mock these context providers properly!
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Protocol Droid Manual', price: 29.99 },
  { id: '2', name: 'Binary Translator', price: 49.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 79.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout Component - Protocol Documentation', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-C3PO-001' });
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('should navigate through all steps and confirm order', async () => {
      // Arrange
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Act - Shipping Step
      await user.type(screen.getByLabelText(/street address/i), '123 Tatooine Way');
      await user.type(screen.getByLabelText(/city/i), 'Mos Eisley');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '12345');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Act - Payment Step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'C-3PO');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Act - Review & Place Order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText('ORD-C3PO-001')).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-C3PO-001');
      expect(mockClearCart).toHaveBeenCalled();
    });
  });

  describe('Form Validation - Oh dear, humans make such errors!', () => {
    it('should display error for invalid ZIP code', async () => {
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'INVALID');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code required/i);
    });

    it('should display error for invalid card number', async () => {
      render(<Checkout />);
      // Navigate to payment first...
      // Assert card validation errors
    });
  });

  describe('Accessibility - Most important protocol!', () => {
    it('should have no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });

  describe('Edge Cases - The probability of errors is high!', () => {
    it('should display empty cart message when no items', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout />);
      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });
});
